/** Compact central-crop RGB signatures generated by build-visual-index.py. */
export interface VisualSignature {
  id: string;
  signature: string;
}

export interface CropRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Keep a square inside the image, shrinking it only when the image is smaller. */
export function squareCrop(
  centerX: number,
  centerY: number,
  size: number,
  imageWidth: number,
  imageHeight: number,
): CropRect {
  if (
    ![centerX, centerY, size, imageWidth, imageHeight].every(Number.isFinite) ||
    size <= 0 ||
    imageWidth <= 0 ||
    imageHeight <= 0
  ) {
    throw new RangeError(
      "Crop coordinates must be finite and dimensions positive.",
    );
  }
  const side = Math.min(size, imageWidth, imageHeight);
  return {
    x: Math.max(0, Math.min(centerX - side / 2, imageWidth - side)),
    y: Math.max(0, Math.min(centerY - side / 2, imageHeight - side)),
    width: side,
    height: side,
  };
}

const RGB_BYTES = 8 * 8 * 3;
const MAX_SQUARED_ERROR = RGB_BYTES * 255 * 255;
const RGB_BASE64 = /^[A-Za-z0-9+/]{256}$/;

/** Rank local suggestions by mean squared RGB error (0 exact, 1 maximally different).
 * Distances are similarities to review, not probabilities of identification.
 */
export function rankVisualMatches(
  pixels: Uint8Array | Uint8ClampedArray,
  items: readonly VisualSignature[],
  limit = 5,
): { id: string; distance: number }[] {
  if (
    !(pixels instanceof Uint8Array || pixels instanceof Uint8ClampedArray) ||
    pixels.length !== RGB_BYTES
  ) {
    throw new RangeError("A query must contain exactly 192 RGB bytes.");
  }
  if (!Number.isSafeInteger(limit) || limit <= 0) {
    throw new RangeError("The result limit must be a positive safe integer.");
  }

  const matches: { id: string; distance: number }[] = [];
  for (const item of items) {
    if (
      !item ||
      typeof item.id !== "string" ||
      item.id.length === 0 ||
      typeof item.signature !== "string" ||
      !RGB_BASE64.test(item.signature)
    )
      continue;

    let rgb: string;
    try {
      rgb = atob(item.signature);
    } catch {
      continue;
    }
    if (rgb.length !== RGB_BYTES) continue;

    let error = 0;
    for (let i = 0; i < RGB_BYTES; i++) {
      const difference = pixels[i] - rgb.charCodeAt(i);
      error += difference * difference;
    }
    matches.push({ id: item.id, distance: error / MAX_SQUARED_ERROR });
  }
  matches.sort(
    (a, b) =>
      a.distance - b.distance || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0),
  );
  return matches.slice(0, limit);
}
